If the second market is just parsing the metadata JSON, it should be a pretty simple code implementation. They can just check both values and OR them.

Ex.
```
const metadata = {
  "777": {
    "7a7c1cd55": {
      "pct": 0.1,
      "addr": "addr123",
      "Token001": {
        "pct": 0.2,
        "addr": "addr456",
      },
      "Token002": {
        "pct": 0.15,
        "addr": "addr789",
      }
    }
  }
}

const policyId = "7a7c1cd55"
const assetName = "Token001"

const royaltyPercent = metadata["777"]?.[policyId]?.[assetName]?.pct || metadata["777"]?.[policyId]?.pct
const royaltyAddress = metadata["777"]?.[policyId]?.[assetName]?.addr || metadata["777"]?.[policyId]?.addr

console.log(royaltyPercent)
console.log(royaltyAddress)
```

