        },
        {
          "type": "script",
          "scriptHash": "<SCRIPT_HASH_2>"
        },
        {
          "type": "script",
          "scriptHash": "<SCRIPT_HASH_3>"
        },
        {
          "type": "script",
          "scriptHash": "<SCRIPT_HASH_4>"
        }
      ]
    },
    {
      "type": "noMore",
      "required": 2,
      "scripts":
      [
        {
          "type": "script",
          "scriptHash": "<SCRIPT_HASH_1>"
        },
        {
          "type": "script",
          "scriptHash": "<SCRIPT_HASH_2>"
